lass="form-grid"><label>Loại giảm giá<select v-model="form.type"><option value="percent">Giảm theo phần trăm (%)</option><option value="fixed">Giảm số tiền (₫)</option></select></label><label>Giá trị giảm<input v-model.number="form.value" type="number" min="1" required :placeholder="form.type==='percent'?'10':'50000'"/></label><label>Đơn hàng tối thiểu<input v-model.number="form.min_order_amount" type="number" min="0" placeholder="0"/><small>Nhập 0 nếu không yêu cầu.</small></label><label v-if="form.type==='percent'">Giảm tối đa<input v-model="form.max_discount_amount" type="number" min="0" placeholder="Không giới hạn"/><small>Bỏ trống để không giới hạn.</small></label></div><div class="section-title"><i class="bi bi-bar-chart-line"/><span>Giới hạn sử dụng</span></div><div class="form-grid"><label>Giới hạn lượt dùng<input v-model="form.usage_limit" type="number" min="1" placeholder="Không giới hạn"/><small>Bỏ trống nếu cho phép dùng không giới hạn.</small></label><div class="preview"><span>Xem trước</span><strong>{{form.code||'MÃ GIẢM GIÁ'}}</strong><small>{{form.type==='percent'?`Giảm ${form.value||0}%`:`Giảm ${money(Number(form.value)||0)}`}}</small></div></div><div class="section-title"><i class="bi bi-calendar3"/><span>Thời gian áp dụng</span></div><div class="form-grid"><label>Bắt đầu<input v-model="form.starts_at" type="datetime-local"/><small>Bỏ trống để áp dụng ngay.</small></label><label>Kết thúc<input v-model="form.ends_at" type="datetime-local"/><small>Bỏ trống nếu không có ngày kết thúc.</small></label></div></div><footer class="coupon-foot"><button type="button" class="btn btn-light" @click="show=false">Hủy</button><button type="submit" class="btn btn-primary"><i class="bi bi-check2-circle me-1"/> Tạo mã giảm giá</button></footer></form></section></div></Teleport></div></template>
